#include <bits/stdc++.h>
using namespace std;
struct State{array<uint16_t,27>x;bool operator==(State const&b)const{return x==b.x;}};
struct Hasher{size_t operator()(State const&s)const{uint64_t h=0x9e3779b97f4a7c15ULL;for(auto x:s.x){h^=x+0x9e3779b97f4a7c15ULL+(h<<6)+(h>>2);}return h;}};
#include "automaton.inc"
int main(int argc,char**argv){int X=argc>1?atoi(argv[1]):21;if(X<1||X>65534){cerr<<"bound must lie in 1..65534\n";return 1;}int cap=X+1;size_t stop=argc>2?atoll(argv[2]):10000000;unordered_set<State,Hasher>seen;vector<State>Q;vector<uint32_t>depth;seen.insert(seed);Q.push_back(seed);depth.push_back(0);set<int>support={1};size_t nextprint=100000;for(size_t pos=0;pos<Q.size();++pos){State st=Q[pos];for(int g=0;g<12;g++){State ns{};for(int i=0;i<27;i++)if(st.x[i])for(auto [j,m]:tr[g][i])ns.x[j]=min(cap,(int)ns.x[j]+st.x[i]*m);int h=0;for(int i:hc)h+=ns.x[i];if(h>X)continue;support.insert(h);if(seen.insert(ns).second){Q.push_back(ns);depth.push_back(depth[pos]+1);if(Q.size()>=stop){cerr<<"resource_limit "<<Q.size()<<" examined "<<pos<<"\n";return 2;}}}if(pos>=nextprint){cerr<<"processed "<<pos<<" queue "<<Q.size()<<" depth "<<depth[pos]<<"\n";nextprint+=100000;}}cout<<"{\"bound\":"<<X<<",\"states\":"<<Q.size()<<",\"max_shortest_word\":"<<*max_element(depth.begin(),depth.end())<<",\"support\":[";bool first=true;for(int h:support){if(!first)cout<<',';cout<<h;first=false;}cout<<"],\"missing_odds\":[";first=true;for(int h=1;h<=X;h+=2)if(!support.count(h)){if(!first)cout<<',';cout<<h;first=false;}cout<<"]}\n";}
